gameActivityClassAdditions.insert:
private TextToSpeech tfgNarratorTts = null;
private boolean tfgNarratorReady = false;
private String tfgNarratorPendingText = null;
private float tfgNarratorPendingPitch = 0.58f;
private float tfgNarratorPendingRate = 0.78f;

private void TFGNarratorSpeakInternal(String text, float pitch, float rate)
{
    if (tfgNarratorTts == null || !tfgNarratorReady || text == null || text.length() == 0)
    {
        tfgNarratorPendingText = text;
        tfgNarratorPendingPitch = pitch;
        tfgNarratorPendingRate = rate;
        return;
    }

    tfgNarratorTts.setPitch(Math.max(0.1f, Math.min(2.0f, pitch)));
    tfgNarratorTts.setSpeechRate(Math.max(0.1f, Math.min(2.0f, rate)));
    tfgNarratorTts.speak(text, TextToSpeech.QUEUE_FLUSH, null, "TFG_OPENING_STORY");
}

public void AndroidThunkJava_TFGNarratorSpeak(final String text, final float pitch, final float rate)
{
    runOnUiThread(new Runnable()
    {
        @Override
        public void run()
        {
            TFGNarratorSpeakInternal(text, pitch, rate);
        }
    });
}

public void AndroidThunkJava_TFGNarratorStop()
{
    runOnUiThread(new Runnable()
    {
        @Override
        public void run()
        {
            tfgNarratorPendingText = null;
            if (tfgNarratorTts != null)
            {
                tfgNarratorTts.stop();
            }
        }
    });
}

gameActivityOnCreateAdditions.insert:
tfgNarratorTts = new TextToSpeech(this, new TextToSpeech.OnInitListener()
{
    @Override
    public void onInit(int status)
    {
        tfgNarratorReady = (status == TextToSpeech.SUCCESS);
        if (tfgNarratorReady)
        {
            tfgNarratorTts.setLanguage(Locale.UK);
            if (tfgNarratorPendingText != null)
            {
                TFGNarratorSpeakInternal(tfgNarratorPendingText, tfgNarratorPendingPitch, tfgNarratorPendingRate);
                tfgNarratorPendingText = null;
            }
        }
    }
});

gameActivityOnDestroyAdditions.insert:
if (tfgNarratorTts != null)
{
    tfgNarratorTts.stop();
    tfgNarratorTts.shutdown();
    tfgNarratorTts = null;
    tfgNarratorReady = false;
}
